    const now = Date.now();
    const activeUsers = Array.from(clients.values()).filter(c => 
        new Date(c.lastSeen).getTime() > now - 10 * 60 * 1000
    ).length;

    res.json({ 
        lanUsers: activeUsers,
        totalClients: clients.size,
